import{_ as e,c as p,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"未濟","description":"高岛易断 - 未濟","frontmatter":{"title":"未濟","description":"高岛易断 - 未濟"},"headers":[],"relativePath":"zh/classics/takashima/064.md","filePath":"zh/classics/takashima/064.md"}'),i={name:"zh/classics/takashima/064.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="未濟" tabindex="-1">未濟 <a class="header-anchor" href="#未濟" aria-label="Permalink to “未濟”">​</a></h1><h2 id="未濟-1" tabindex="-1">未濟 <a class="header-anchor" href="#未濟-1" aria-label="Permalink to “未濟”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>未济：亨，小狐汔济，濡其尾，无攸利。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>不曰不济，而曰“未济”，非安处不济也，未耳。盖《未济》而自有可济，亦未亨而自有可亨，故曰“未济亨”。《坎》为小狐，“汔”，几也。济必登岸，始为《既济》，一步不至，犹未也，“汔济”安得为济哉！小狐力弱，中流失济，尾重不掉，难免濡矣，复有何利？故曰“小狐汔济，濡其尾，无攸利”也。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>火在水上，未济。君子以慎辨物居方。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>火热水寒，物之各异其性也；《离》南《坎》北，方之各殊其位也。火在水上，是炎上润下，并失其位，两不相济也，故曰《未济》。君子观其象，而辨之居之，辨其物，使物得其宜，而不相混，居其方，使方从其位，而不相越。皆以审慎而出之，斯知之无不明，处之无不当，而其未济者乃可进于济矣，故曰“君子以慎辨物居方”。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：运途颠倒，诸事须慎。</p><p>○　问营商：货物失当，地位不合，所当谨慎处置，方可获利。</p><p>○　问功名：未也。</p><p>○　问战征：营垒器具，各失所宜，不相为用，急宜慎重审察，斯可免败。</p><p>○　问家宅：方向倒置，须当改易。</p><p>○　问婚姻：门户不合。</p><p>○　问疾病：上下焦血络不通，宜升不升，宜降不降，药方最宜审慎。</p><p>○　问失物：辨明方位，可以寻得。</p><p>○　问六甲：上月生女，下月生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初居《未济》之始，《彖》所云“小狐汔济，濡其尾”，初爻当之。《未济》之初，与《既济》之上，首尾相接，《既济》之上，以濡首而厉，初踵其后，见上之濡首，反而自惩，未济者亦可免于濡矣，乃前首后尾，同遭其濡，顽不知戒，故曰“吝”也。《象传》以“亦不知极”释之，谓前覆其辙，后又不知而蹈之，故曰亦术知其极也。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问时运：不审前后，不顾进退，鲁莽从事，是昏而无知者也。</p><p>○　问营商：前既失败，后又不戒，覆辙相仍，其将何以了事乎？</p><p>○　问功名：龙头既失，骥尾亦必难附。</p><p>○　问婚姻：流离首尾，团聚难矣。</p><p>○　问家宅：此宅前门后户，方位不正。</p><p>○　问疾病：病在下身。</p><p>○　问六甲：生男。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某来，请占制造物品生业如何，筮得《未济》之《睽》。</p><p>断曰：初居《未济》之初，正在济末将济之时，《既济》之终“濡其首”，《未济》之始“濡其尾”，有首尾不相顾之象。今君占制造生业，得此爻辞，知此业必是旧业，君接其后而重兴也。君乃不知前车之覆，贸然而蹈其后，以致制品所出，一时不能销售。以此质金，反致失利，得失不偿，进退两难，几同“小狐汔济”，而“濡其尾”也，未免吝矣。至二爻曰“曳其轮，贞吉”，在明年当以车运出外，可以贩卖获利也，君可无忧焉。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>二居《坎》之中，《坎》为轮，故曰“轮”。轮者，济之具也。《既济》初爻曰曳轮而濡尾，有济之具而濡者也；此曰曳轮，而不曰濡尾，有济之具而不濡者也，视《既济》之初为优矣，故曰“贞吉”。《坎》又为矫輮，按《周礼·考工记》，“行泽者反輮，行山者仄輮”，取其便于曳也。御轮济水，中道而行，其济以正，是为中行以正，吉何如之！《象传》所释，最为明著。</p><h2 id="九二占" tabindex="-1">九二占 <a class="header-anchor" href="#九二占" aria-label="Permalink to “九二占”">​</a></h2><p>○　问时运：运如轻车渡水，中道以济，无往不利。</p><p>○　问营商：有满载而归之象。</p><p>○　问功名：二与五应，五为君，二为臣，二五皆吉，是君臣相济也。有后车以载之象。</p><p>○　问战征：有曳柴伪遁之谋。</p><p>○　问婚姻：有桓少君鹿车共挽之风，必得贤妇，吉。</p><p>○　问家宅：有轮奂并美之象。</p><p>○　问疾病：必是胸腹作鸣，辘辘如车声，宜开通三焦，使气机舒展，自愈。</p><p>○　问六甲：生男。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>明治八年九月，朝鲜国炮击我云扬舰，物论汹汹，朝廷将兴问罪之师。时陆军大佐某氏来请一占，筮得《未济》之《晋》。</p><p>断曰：水火不交，不相为用，谓之《未济》。然未济非不济也，时未至则不济，时至则济，故曰“未济亨”。为卦皆取水火，《既济》水在火上，初爻曰曳轮，是为陆道之轮车也；《未济》火在水上，二爻曰曳轮，是为海道之轮船也。今云扬舰被朝鲜炮击，爻曰“曳其轮，贞吉”，想虽被击，尚可曳轮而归，故不失其吉也。《象传》曰“中以行正”，言必得中和之道，以行其正，今年必不致构怨兴兵也。至三爻曰“征凶，利涉大川”，恐明年有事于朝鲜。曰“征凶”者，恐陆军不利；曰“利涉大川”者，知海军必大胜也。九四曰“贞吉，悔亡，震用伐鬼方，三年有赏于大国”，自二至四为后年，必可解决朝鲜之事矣。且二爻变而为《晋》，晋者，进也，《晋》五曰“失得勿恤，往吉，无不利”；上曰“晋其角，维用伐邑，厉吉，无咎”，是皆征伐有功之占也。占象如是，知以后必获大功。但《未济》以外卦为《既济》，内卦为将济，占在二爻，故今年未能成事，必待外卦，乃得全济也。后朝鲜事局平和，征讨不兴，于是某氏来曰：前日之占，事未甚验，余曰：《易》占无不灵应，但所应有不在一时也。现虽归和平，其“中以行正”一语，恰好符合，此后占象，君须缓以待之，无不应也。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>三爻以阴居阳，当内外卦之交，首尾俱不着岸，故爻曰“未济”。专以卦名归之，谓《未济》之所以未济者，在此爻也。三为《坎》之，地当重要，进一步则出险，误一步即履危，鲁莽前进，一经失足，功败垂成，故曰“征凶”。然《未济》有可济之道，有险有出险之时，自古定大难，建大功者，罔非从“征凶”之时而兴起也。所谓“征凶”者，第戒其不可妄动，非欲其退缩不前。三之地，正当利涉之地，三之时，正当利涉之时，此而不济，则终不济矣，此而得济，则汔济者乃得济矣。《象传》曰“位不当也”，《未济》六爻，位皆不当，三为《坎》之终，故《传》专以不当释之。</p><h2 id="六三占" tabindex="-1">六三占 <a class="header-anchor" href="#六三占" aria-label="Permalink to “六三占”">​</a></h2><p>○　问时运：宜镇静待时，躁动则凶。</p><p>○　问战征：宜会集海军，水陆并进，则凶者吉矣。</p><p>○　问营商：以舟运为利。</p><p>○　问功名：有涉川作楫之材。</p><p>○　问婚姻：《诗》云“造舟为梁，亲迎于渭”，迎娶则吉，往赘则凶。</p><p>○　问疾病：《艮》为狐，病由狐祟所致，宜涉川以避。</p><p>○　问六甲：生男。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>三十年，占众议院气运，筮得《未济》之《鼎》。</p><p>断曰：此卦火上水下，水火不相为用，故曰“未济”。三爻居上下内外之交，出《坎》入《离》，正当《未济》之时，是以爻辞直曰“未济”。曰“征凶”者，指初之濡尾也；曰“利涉”者，指二之曳轮也，为利为凶，任人自为之耳。《传》则释曰“位不当”，于此即可见众议院之气运矣。盖在政府欲效欧美之文明，以图富强；在众议员，欲学欧美之自由，以图权利，犹之火上水下，两不相济也。且现时所选议员，多由贿赂而来，是明明位之不当也，由此以往，安得不凶？故曰“征凶”。然于议院之设，苟当其位，而“中以行正”，未始无利，故曰“利涉大川”。但此爻处《坎》之终，犹未出险，今年众议院，正当未济之地，难期盛旺。四爻曰“贞吉，悔亡，震用伐鬼方，三年有赏于大国”，知明年众议院，必得其人，能赞襄国家大事，劳邀厚赐，此盛象也。五曰“君子之光”，五为君，定当入观天颜，武功文德，并焕辉光矣。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>《未济》济在四，《既济》济在三，《未济》之四，即《既济》之三，故爻辞皆曰“伐鬼方”。三居《离》之始，《离》为戈兵，故“用伐”。《坎》为鬼，故取象于“鬼方”。“震”者，威怒之象，所谓一怒而安天下之民也。《未济》则有悔，济则悔亡。故曰“贞吉，悔亡”。“三年”者，言其久也，即《既济》三爻所云“三年克之”也。“有赏”者，为献俘授馘饮，至大赏是也。“大国”谓殷，爻虽不明言高宗，要不出《既济》三爻之义也。《象传》曰“志行”，谓班师奏凯，威震遐方，主三军者，得行其志矣。《既济》三爻《传》曰“惫也”，为劳师远征而言；此《传》曰“志行”，为振旅告捷而言。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问时运：有此大运，“贞吉，悔亡”，名利俱全。</p><p>○　问战征：率军远征，奏凯而还，得以荣邀赐命。</p><p>○　问营商：行商远出，财利丰盈。</p><p>○　问功名：声名远震，得承天宠。</p><p>○　问婚姻：三年可成。</p><p>○　问家宅：贞吉。</p><p>○　问疾病：“鬼方”二字不祥，三年后恐难保。</p><p>○　问六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>友人某来请占气运，筮得《未济》之《蒙》。</p><p>断曰：此卦下三爻为《未济》之时，上三爻为《既济》之时，今占得四爻，知年来困苦之事，渐》次可奏成功，谓之“贞吉，悔亡”。“震用伐鬼方，三年有赏于大国”者，知君于此三年中，得以威名远扬，赏赐荣膺，为生平业成志满之时也。</p><p>明治二十七年冬至，谨占二十八年圣运，筮得《未济》之《蒙》。</p><p>断曰：四爻当内外之交，出《坎》入《离》，为脱险难而进文明，是由《未济》而抵《既济》也。今占得四爻，爻曰“震用伐鬼方”，是为征清得胜也；“三年”者，谓战役之久；“有赏于大国”者，谓奏凯行赏也。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>五为《未济》一卦之主，居《离》之中，与四相比，与二相应。二以居中行正，四以征伐有功，当此文德昭明，武功显著；臣下之勋业，要即为天子之威光也，故曰“君子之光”。柔得中，故“贞吉，无悔”。《离》为明，为光，德莫盛于明，业莫大于光，六五之君，和顺积中，英华发外，其光皆出于君子之身，天下莫不仰文明之化，故曰“有孚，吉”。《象传》以“晖吉”释之，谓其笃实辉光，自然昭著，吉何如也！</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问时运：运当全盛，百事皆吉。</p><p>○　问战征：《师》卦曰“师贞，丈人吉”，可并占之。</p><p>○　问营商：其营业必关系政府公干，或为军饷，或为军器，得沾朝廷之余泽，故吉。</p><p>○　问功名：有入觐天颜之象。</p><p>○　问家宅：此宅大吉，当邀旌赐之劳。</p><p>○　问婚姻：“君子好逑”，必得。</p><p>○　问六甲：生女，主贵。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>某缙绅来，请占官阶升迁，筮得《未济》之《讼》。</p><p>断曰：五爻居《离》之中，《离》为日，为光，五当君位，日有君象，故曰“君子之光”。日光照临，下土遍被，故曰“有孚”。五与二应，二为臣，是先得“君子之光”者也。今足下占禄位升，得《未济》五爻，五为尊位，二爻属贵下，二爻曰“曳其轮，贞吉”，轮为日轮，曳轮者，有如羲和御日，是为天子之近臣，沐浴圣化，瞻仰龙光，君明臣良，可为贵下贺焉。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上爻当《未济》之终，反为《既济》，坎险已脱，上下交孚，则饮食以燕乐之。《诗》“南有嘉鱼，君子有酒，嘉宾式燕以乐”，《序》曰太平君子至诚。乐与贤者共之，有孚于酒食之义也，故“无咎”。然酒以成礼，不及于乱，立监立史，所以示其节也，“濡其首”，则醉而不出，是谓伐德，亦何取于孚矣，故曰“有孚失是”。是始为有孚而饮酒者，继反为饮酒而失孚也，《象传》以“不知节”释之。《易》之为书，患太过，更甚于防不及，欲不可纵，乐不可极，持盈保泰，无非节也。此特于《未济》之终，借饮酒以为喻耳。</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问时运：《坎》难已平，众心欢乐，能知撙节，可以永保无咎。</p><p>○　问战征：此为得胜班师，饮酒策勋之时也。</p><p>○　问营商：已得厚利而归，从此量入为出，富可永保矣。</p><p>○　问功名：有得而复失之患。</p><p>○　问疾病：必是饮食不节所致。</p><p>○　问讼事：《序卦》曰“饮食必有讼”，知其讼必由于酗酒来也。</p><p>○　问六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>二十八年七月廿七日薄暮，余与友闲叙于书楼，偶闻有叫新闻号外者，客曰：号外所报，不审何事，君试占之。筮得《未济》之《解》。</p><p>断曰：号外所报，必因饮酒过度，醉溺水中之祸也。时女仆适赍号外来，展而阅之，为山阳铁道，汽车颠覆中途，致伤旅客之报也。后数日，会该铁道会社员，问及当时情况，曰：会风雨暴作，劝令止车，机关师某不肯，临行且满酌火酒，启车而进，猝罹此祸，因此伤命云。乃知爻辞，果不虚也。</p>',102)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
